css:
/* Style the text loader element */
.text-loader {
  font-weight: bold; /* Bold text for emphasis */
  font-family: sans-serif; /* Clean, modern font */
  font-size: 30px; /* Readable size */
  animation: fadeEffect 1s linear infinite alternate; /* Fade animation */
}

/* Add the "Loading..." text via pseudo-element */
.text-loader::before {
  content: "Loading..."; /* Default text content */
}

/* Define the fade animation */
@keyframes fadeEffect {
  to { opacity: 0; } /* Fade out at the end of the cycle */
}
